const clampText = (value, maxLen = 1024) => {
  if (value === undefined || value === null) return null;
  const str = String(value).trim();
  if (!str) return null;
  return str.length > maxLen ? str.slice(0, maxLen) : str;
};

const maskIpv4 = (ip) => {
  const parts = ip.split('.');
  if (parts.length !== 4) return null;
  const nums = parts.map((p) => Number.parseInt(p, 10));
  if (nums.some((n) => Number.isNaN(n) || n < 0 || n > 255)) return null;
  return `${nums[0]}.${nums[1]}.${nums[2]}.0`;
};

const maskIpv6 = (ip) => {
  const cleaned = ip.split('%')[0];
  const hextets = cleaned.split(':').filter((h) => h.length > 0);
  if (hextets.length === 0) return null;
  const prefix = hextets.slice(0, 3).join(':');
  return `${prefix}::`;
};

const maskIp = (rawIp) => {
  const ip = (rawIp || '').toString().trim();
  if (!ip) return null;

  const v4Match = ip.match(/::ffff:(\d+\.\d+\.\d+\.\d+)$/i);
  if (v4Match) {
    return maskIpv4(v4Match[1]);
  }

  if (ip.includes('.')) {
    return maskIpv4(ip);
  }

  if (ip.includes(':')) {
    return maskIpv6(ip);
  }

  return null;
};

const normalizeIngestPath = ({ ingestPath, req, defaultPath = '/analytics' } = {}) => {
  const safeIngestPathRaw = clampText(ingestPath, 32);
  const v = (safeIngestPathRaw || '').toString().trim();
  if (v === '/analytics' || v === '/a' || v === 'server') return v;

  try {
    const base = (req?.baseUrl || '').toString();
    if (base.startsWith('/api/analytics')) return '/analytics';
    if (base.startsWith('/api/a')) return '/a';
  } catch (_) {}

  return defaultPath;
};

module.exports = {
  clampText,
  maskIp,
  normalizeIngestPath,
};
